const express = require('express');
const { spawn } = require('child_process');

const app = express();

app.get('/api/analytics/forecast', (req, res) => {
  if (!req.user || !req.user.companyId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Reject untrusted query companyId; strictly enforce caller's authenticated companyId
  const targetCompanyId = req.query.companyId || req.user.companyId;
  if (targetCompanyId !== req.user.companyId && req.user.role !== 'PLATFORM_ANALYST') {
    return res.status(403).json({ error: 'Access denied: cannot generate forecast for another company' });
  }

  const pyProcess = spawn('python3', [
    'scripts/generate_sales_forecast.py',
    '--company-id',
    req.user.companyId
  ]);

  let output = '';
  pyProcess.stdout.on('data', (data) => {
    output += data.toString();
  });

  pyProcess.on('close', (code) => {
    if (code === 0) {
      res.setHeader('Content-Type', 'application/json');
      res.send(output);
    } else {
      res.status(500).json({ error: 'Forecasting script failed' });
    }
  });
});

app.listen(6001);
